/**
 * Shared facts about the committed reference exchange archive.
 *
 * The archive itself is generated by `exchange-reference-archive.test-helper.ts`; this module stays
 * free of server imports so the Playwright proofs can use the same constants without resolving the
 * `$lib` aliases of the application build.
 */

/** Repository-relative path of the committed reference archive. */
export const referenceArchivePath = 'fixtures/exchange/reference-archive.zip';

/** Account that the takeover selects as instance administrator. */
export const referenceAdminUsername = 'avery';

/** Account whose native legacy hash must survive the import and be rehashed on first sign-in. */
export const referenceLegacyUsername = 'blake';

/** Account whose unsupported hash must be dropped and replaced by a password reset. */
export const referenceIncompatibleUsername = 'casey';

/** Plaintext password behind the carried-over legacy hash of {@link referenceLegacyUsername}. */
export const referenceLegacyPassword = 'reference-passphrase-blake';
